import random

def is_3_regular(edges, n):
    degrees = [0] * n
    for u, v in edges:
        degrees[u] += 1
        degrees[v] += 1
    return all(d == 3 for d in degrees)

def get_girth(edges, n):
    import collections
    adj = collections.defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_girth = float('inf')
    for i in range(n):
        dist = {i: 0}
        parent = {i: None}
        queue = collections.deque([i])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    min_girth = min(min_girth, dist[u] + dist[v] + 1)
    return min_girth

